# VexelRay installer - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
#   irm https://raw.githubusercontent.com/sibarum/vexelray-dist/main/install.ps1 | iex
#
# Installs every application in the suite, each as an install of its own: its own folder, its own
# entry in Settings > Apps, its own updater and uninstaller. This script installs nothing itself. For
# each application it fetches the published install manifest, downloads that application's own
# install.ps1, checks it against the SHA-256 the manifest records, and runs it.
#
# Options (set as environment variables before running the line above):
#   INSTALL_ONLY=a,b           install only these applications (vexplore, text-editor, pix, mainframe, calculator, fluid-sim, rigid-sim, maistro, inspector); an optional one is
#                              installed only when named here or ticked, or kept up to date once installed
#   INSTALL_NO_SHORTCUTS=1     passed on to every application's installer
#   INSTALL_NO_PATH=1          "
#   INSTALL_NO_ASSOCIATIONS=1  "
#   INSTALL_FORCE=1            "
#   INSTALL_SKIP_CHECKS=1      "
#   INSTALL_QUIET=1            no window: ask nothing and report in the console only
#   INSTALL_EVERYTHING=1       the optional applications too, like the rest
# Or as arguments, to the script run from a file or as a script block:
#   & ([scriptblock]::Create((irm https://raw.githubusercontent.com/sibarum/vexelray-dist/main/install.ps1))) --install-everything --do-not-prompt-me
#   --install-everything       INSTALL_EVERYTHING=1
#   --do-not-prompt-me         INSTALL_QUIET=1 (-Quiet is the same)
# INSTALL_VERSION and INSTALL_DIR name one application's version and folder, so they are not passed
# on: run that application's own installer to use them. An application this script pins to a version
# (a preflight of snapshot builds) is installed at that version, and reinstalled even when it is current.
#
# Run from a console a person is at, the installer opens one window: a box for each application (those in
# INSTALL_ONLY, or else those not installed or out of date, are ticked) and the shortcut, PATH and file-type
# choices for all of them, then each application's progress, then what happened to each. The applications'
# own installers run quietly inside it. It stays in the console when INSTALL_QUIET is set (or
# --do-not-prompt-me or -Quiet is passed), under CI, with -NonInteractive, or when its output is redirected.

$SuiteCfg = '{"name":"VexelRay","members":[{"id":"vexplore","name":"Vexplore","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/vexplore/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs"},{"id":"text-editor","name":"Vex","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/text-editor/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs"},{"id":"pix","name":"Pix","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/pix/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs"},{"id":"mainframe","name":"MainFrame","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/mainframe/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs"},{"id":"calculator","name":"Calculator","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/calculator/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs"},{"id":"fluid-sim","name":"Fluid Sim","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/fluid-sim/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","optional":true},{"id":"rigid-sim","name":"Rigid Sim","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/rigid-sim/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","optional":true},{"id":"maistro","name":"Maistro","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/maistro/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","optional":true},{"id":"inspector","name":"VexelRay Inspector","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/inspector/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","optional":true}]}' | ConvertFrom-Json

# The window, when there is one: SuiteLog copies console output into it, and is a no-op without it.
function SuiteLog([string]$m) {
    if ($SuiteUi -and -not $SuiteUi.Closed) { $SuiteUi.Log.AppendText("$m`r`n"); [Windows.Forms.Application]::DoEvents() }
}
function SuiteSay([string]$m, [string]$color) {
    if ($color) { Write-Host $m -ForegroundColor $color } else { Write-Host $m }
    SuiteLog $m
}
function SuiteBar([int]$pct) {
    if (-not $SuiteUi -or $SuiteUi.Closed) { return }
    if ($pct -lt 0) { $SuiteUi.Bar.Style = 'Marquee' } else { $SuiteUi.Bar.Style = 'Continuous'; $SuiteUi.Bar.Value = [Math]::Min(100, $pct) }
}

function SuiteSha([string]$p) { (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant() }

function SuiteRegistryDir($m) {
    if ($env:INSTALL_REGISTRY_DIR) { return $env:INSTALL_REGISTRY_DIR }
    [Environment]::ExpandEnvironmentVariables($m.registryDir)
}

function SuiteRecord($m) {
    $p = Join-Path (SuiteRegistryDir $m) "$($m.id).json"
    if (-not (Test-Path -LiteralPath $p)) { return $null }
    try { Get-Content -Raw -LiteralPath $p | ConvertFrom-Json } catch { $null }
}

function SuiteRecordVersion($m) { (SuiteRecord $m).version }

function SuiteStatusCode($err) {
    $e = $err.Exception
    while ($e) {
        if ($e.Response -and $e.Response.StatusCode) { return [int]$e.Response.StatusCode }
        $e = $e.InnerException
    }
    return 0
}

# Invoke-WebRequest -OutFile, or with a window a chunked download that keeps the window responsive and
# stops when Cancel is pressed.
function SuiteDownload([string]$url, [string]$out) {
    if (-not $SuiteUi -or $SuiteUi.Closed) { Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $out; return }
    [Windows.Forms.Application]::DoEvents()
    $req = [Net.WebRequest]::Create($url)
    $req.UserAgent = 'vexelray-installer'
    $resp = $req.GetResponse()
    try {
        $in = $resp.GetResponseStream()
        $fs = [IO.File]::Create($out)
        try {
            $buf = New-Object byte[] 65536
            while (($n = $in.Read($buf, 0, $buf.Length)) -gt 0) {
                $fs.Write($buf, 0, $n)
                [Windows.Forms.Application]::DoEvents()
                if ($SuiteUi.Action -eq 'secondary') { throw 'Cancelled.' }
            }
        } finally { $fs.Dispose(); $in.Dispose() }
    } finally { $resp.Close() }
}

# The member's published manifest, or $null when it is not published yet.
function SuiteFetchManifest($m, [string]$tmp) {
    $mf = "$tmp\$($m.id).manifest.json"
    try {
        SuiteDownload $m.manifestUrl $mf
    } catch {
        if ((SuiteStatusCode $_) -eq 404) { return $null }
        throw
    }
    $manifest = Get-Content -Raw -LiteralPath $mf | ConvertFrom-Json
    if ($manifest.id -ne $m.id) { throw "the manifest at $($m.manifestUrl) is for '$($manifest.id)', not '$($m.id)'" }
    $manifest
}

# The version to install: the member's pinned version (a preflight suite of snapshot builds), or else the
# manifest's latest. $null when the manifest does not list the pinned version.
function SuiteWant($m, $manifest) {
    if (-not $m.version) { return $manifest.latest }
    if (@($manifest.versions | Where-Object { $_.version -eq $m.version }).Count -gt 0) { return $m.version }
    return $null
}

# Whether the window's check found the member (or its pinned version) not published. $manifests may be $null.
function SuiteUnpublished($m, $manifests) {
    if (-not $manifests -or -not $manifests.ContainsKey($m.id)) { return $false }
    $mf = $manifests[$m.id]
    -not $mf -or -not (SuiteWant $m $mf)
}

# A member installer's console output, shown in the console as it would be and copied into the window;
# its steps become the status line.
function SuiteEcho($o, [string]$who) {
    if ($o -is [Management.Automation.WarningRecord]) {
        Write-Warning $o.Message
        SuiteLog "    Warning: $($o.Message)"
        return
    }
    if ($o -isnot [Management.Automation.InformationRecord]) { return }
    $d = $o.MessageData
    if ($d -is [Management.Automation.HostInformationMessage]) {
        $text = [string]$d.Message
        if ($null -ne $d.ForegroundColor) { Write-Host $text -ForegroundColor $d.ForegroundColor -NoNewline:([bool]$d.NoNewLine) }
        else { Write-Host $text -NoNewline:([bool]$d.NoNewLine) }
    } else {
        $text = [string]$d
        Write-Host $text
    }
    if ($SuiteUi -and -not $SuiteUi.Closed) {
        if ($text.StartsWith('==> ')) { $SuiteUi.Status.Text = "${who}: $($text.Substring(4))"; SuiteBar -1 }
        if ($text -match 'Diagnostic report: (.+)$') { $SuiteUi.Report = $Matches[1].Trim() }
    }
    SuiteLog $text
}

# Returns one of: installed, unpublished, failed. $manifests holds the manifests the window already fetched.
function SuiteInstallOne($m, [string]$tmp, $manifests) {
    SuiteSay ""
    SuiteSay "==> $($m.name)" Cyan
    try {
        if ($manifests -and $manifests.ContainsKey($m.id)) { $manifest = $manifests[$m.id] }
        else { $manifest = SuiteFetchManifest $m $tmp }
        if (-not $manifest) {
            SuiteSay "    $($m.name) has not been published yet; skipped." Yellow
            return 'unpublished'
        }
        $want = SuiteWant $m $manifest
        if (-not $want) {
            SuiteSay "    $($m.name) $($m.version) has not been published yet; skipped." Yellow
            return 'unpublished'
        }
        $tool = $manifest.tools.'install.ps1'
        if (-not $tool -or -not $tool.url -or -not $tool.sha256) { throw "the manifest names no install.ps1" }
        $script = "$tmp\$($m.id).install.ps1"
        SuiteDownload $tool.url $script
        if ((SuiteSha $script) -ne $tool.sha256) {
            throw "its install.ps1 does not match the SHA-256 in its manifest; it was not run"
        }
        # A script block of its own, so each installer's functions stay in its own scope. It reports its
        # own errors and does not throw, so whether it worked is read from the record it writes. With a
        # window it shows its downloads there ($ViHostUi), and its output is copied into the window's log.
        $ViHostUi = $SuiteUi
        $sb = [scriptblock]::Create([IO.File]::ReadAllText($script))
        # A pinned version is installed even over itself: a snapshot is rebuilt under the same version.
        $force = $env:INSTALL_FORCE
        if ($m.version) { $env:INSTALL_VERSION = $want; $env:INSTALL_FORCE = '1' }
        try {
            if ($SuiteUi) { & $sb 6>&1 3>&1 | ForEach-Object { SuiteEcho $_ $m.name } | Out-Null }
            else { $null = & $sb }
        } finally {
            [Environment]::SetEnvironmentVariable('INSTALL_VERSION', $null, 'Process')
            [Environment]::SetEnvironmentVariable('INSTALL_FORCE', $force, 'Process')
        }
        if ((SuiteRecordVersion $m) -eq $want) { return 'installed' }
        return 'failed'
    } catch {
        SuiteSay "ERROR: $($m.name): $($_.Exception.Message)" Red
        return 'failed'
    }
}

# ---- window ----------------------------------------------------------------------------
# As in an application's own installer, everything runs on this one thread: the window's event handlers
# only set $SuiteUi.Action, the install code reads it, and Application.DoEvents (from SuiteLog,
# SuiteDownload, the member installers' downloads and SuiteUiWait) keeps the window responsive. The
# handlers are closures, so they touch $ui and .NET objects only, never the Suite* functions.

function SuiteWantsWindow([bool]$quiet) {
    if ($quiet -or ($env:INSTALL_QUIET -and $env:INSTALL_QUIET -ne '0') -or $env:CI) { return $false }
    if (-not [Environment]::UserInteractive) { return $false }
    if (@([Environment]::GetCommandLineArgs() | Where-Object { $_ -match '^[-/]noni' }).Count -gt 0) { return $false }
    try { if ([Console]::IsOutputRedirected) { return $false } } catch { }
    try { Add-Type -AssemblyName System.Windows.Forms, System.Drawing; return $true } catch { return $false }
}

function SuiteUiOpen($members) {
    try {
        if (-not ('ViWin.ViDpi' -as [type])) {
            Add-Type -Namespace ViWin -Name ViDpi -MemberDefinition '[DllImport("user32.dll")] public static extern bool SetProcessDPIAware();'
        }
        [void][ViWin.ViDpi]::SetProcessDPIAware()
    } catch { }
    [Windows.Forms.Application]::EnableVisualStyles()
    $ui = @{ Action = $null; Closed = $false; Phase = 'busy'; Report = $null }
    $n = @($members).Count

    $f = New-Object Windows.Forms.Form
    $f.SuspendLayout()
    $f.AutoScaleDimensions = New-Object Drawing.SizeF(96, 96)
    $f.AutoScaleMode = [Windows.Forms.AutoScaleMode]::Dpi
    $f.Font = New-Object Drawing.Font('Segoe UI', 9)
    $f.Text = "$($SuiteCfg.name) Setup"
    $f.FormBorderStyle = 'FixedDialog'
    $f.MaximizeBox = $false
    $f.StartPosition = 'CenterScreen'
    $f.ClientSize = New-Object Drawing.Size(580, [Math]::Max(420, 340 + 26 * $n))

    $head = New-Object Windows.Forms.Panel
    $head.Dock = 'Top'; $head.Height = 68; $head.BackColor = [Drawing.SystemColors]::Window
    $title = New-Object Windows.Forms.Label
    $title.AutoSize = $true; $title.Location = New-Object Drawing.Point(18, 12)
    $title.Font = New-Object Drawing.Font('Segoe UI Semibold', 12)
    $sub = New-Object Windows.Forms.Label
    $sub.AutoSize = $false; $sub.Location = New-Object Drawing.Point(19, 40); $sub.Size = New-Object Drawing.Size(545, 20)
    $sub.AutoEllipsis = $true; $sub.ForeColor = [Drawing.SystemColors]::GrayText
    $head.Controls.AddRange(@($title, $sub))
    $rule = New-Object Windows.Forms.Panel
    $rule.Dock = 'Top'; $rule.Height = 1; $rule.BackColor = [Drawing.SystemColors]::ControlDark

    $bar = New-Object Windows.Forms.Panel
    $bar.Dock = 'Bottom'; $bar.Height = 50
    $flow = New-Object Windows.Forms.FlowLayoutPanel
    $flow.Dock = 'Right'; $flow.FlowDirection = 'RightToLeft'; $flow.AutoSize = $true; $flow.WrapContents = $false
    $flow.Padding = New-Object Windows.Forms.Padding(0, 10, 10, 0)
    $b2 = New-Object Windows.Forms.Button
    $b1 = New-Object Windows.Forms.Button
    foreach ($b in $b2, $b1) {
        $b.AutoSize = $true; $b.MinimumSize = New-Object Drawing.Size(92, 28); $b.Margin = New-Object Windows.Forms.Padding(6, 0, 0, 0)
    }
    $flow.Controls.AddRange(@($b2, $b1))
    $bar.Controls.Add($flow)

    $body = New-Object Windows.Forms.Panel
    $body.Dock = 'Fill'; $body.Padding = New-Object Windows.Forms.Padding(18, 14, 18, 6)

    # options page: a box for each application, with what it would install beside it, then the choices
    # that apply to all of them
    $opts = New-Object Windows.Forms.Panel
    $opts.Dock = 'Fill'
    $appsLabel = New-Object Windows.Forms.Label
    $appsLabel.Text = 'Applications'; $appsLabel.AutoSize = $true; $appsLabel.Location = New-Object Drawing.Point(0, 2)
    $opts.Controls.Add($appsLabel)
    $picks = @{}; $infos = @{}
    $y = 24
    foreach ($m in $members) {
        $cb = New-Object Windows.Forms.CheckBox
        $cb.AutoSize = $true; $cb.Location = New-Object Drawing.Point(2, $y); $cb.Text = $m.name
        $info = New-Object Windows.Forms.Label
        $info.AutoSize = $false; $info.Location = New-Object Drawing.Point(230, ($y + 3)); $info.Size = New-Object Drawing.Size(314, 20)
        $info.AutoEllipsis = $true; $info.ForeColor = [Drawing.SystemColors]::GrayText
        $opts.Controls.AddRange(@($cb, $info))
        $picks[$m.id] = $cb; $infos[$m.id] = $info
        $y += 26
    }
    $y += 12
    $allLabel = New-Object Windows.Forms.Label
    $allLabel.Text = 'For all of them'; $allLabel.AutoSize = $true; $allLabel.Location = New-Object Drawing.Point(0, $y)
    $opts.Controls.Add($allLabel)
    $y += 22
    $cbs = @()
    foreach ($i in 0..2) {
        $cb = New-Object Windows.Forms.CheckBox
        $cb.AutoSize = $true; $cb.Location = New-Object Drawing.Point(2, $y); $cb.Visible = $false
        $cbs += $cb; $y += 28
    }
    $note = New-Object Windows.Forms.Label
    $note.Dock = 'Bottom'; $note.Height = 40; $note.ForeColor = [Drawing.SystemColors]::GrayText
    $note.Text = "Each application is installed by its own installer, into a folder of its own, after it is checked against the SHA-256 its publisher recorded. No administrator rights are needed."
    $opts.Controls.Add($note)
    $opts.Controls.AddRange($cbs)

    # progress page: a row for each application, then status, bar and log
    $prog = New-Object Windows.Forms.Panel
    $prog.Dock = 'Fill'; $prog.Visible = $false
    $log = New-Object Windows.Forms.TextBox
    $log.Dock = 'Fill'; $log.Multiline = $true; $log.ReadOnly = $true; $log.ScrollBars = 'Vertical'
    $log.Font = New-Object Drawing.Font('Consolas', 9); $log.BackColor = [Drawing.SystemColors]::Window
    $gap = New-Object Windows.Forms.Panel
    $gap.Dock = 'Top'; $gap.Height = 10
    $pbar = New-Object Windows.Forms.ProgressBar
    $pbar.Dock = 'Top'; $pbar.Height = 18; $pbar.MarqueeAnimationSpeed = 30; $pbar.Style = 'Marquee'
    $status = New-Object Windows.Forms.Label
    $status.Dock = 'Top'; $status.Height = 38; $status.AutoEllipsis = $true
    $rows = New-Object Windows.Forms.Panel
    $rows.Dock = 'Top'; $rows.Height = 24 * $n + 10
    $states = @{}
    $y = 0
    foreach ($m in $members) {
        $nl = New-Object Windows.Forms.Label
        $nl.AutoSize = $true; $nl.Location = New-Object Drawing.Point(0, $y); $nl.Text = $m.name
        $sl = New-Object Windows.Forms.Label
        $sl.AutoSize = $true; $sl.Location = New-Object Drawing.Point(230, $y); $sl.ForeColor = [Drawing.SystemColors]::GrayText
        $rows.Controls.AddRange(@($nl, $sl))
        $states[$m.id] = $sl
        $y += 24
    }
    # docking runs from the last control added to the first, so they are added bottom-up
    $prog.Controls.AddRange(@($log, $gap, $pbar, $status, $rows))

    $body.Controls.AddRange(@($opts, $prog))
    $f.Controls.AddRange(@($body, $rule, $head, $bar))
    $f.AcceptButton = $b1

    $ui.Form = $f; $ui.Title = $title; $ui.Sub = $sub; $ui.B1 = $b1; $ui.B2 = $b2
    $ui.Options = $opts; $ui.Picks = $picks; $ui.Infos = $infos; $ui.Checks = $cbs; $ui.Progress = $prog
    $ui.States = $states; $ui.Status = $status; $ui.Bar = $pbar; $ui.Log = $log

    $b1.add_Click({ $ui.Action = 'primary' }.GetNewClosure())
    $b2.add_Click({ $ui.Action = 'secondary' }.GetNewClosure())
    # closing is cancelling while downloading, and is refused while busy
    $f.add_FormClosing({
        param($s, $e)
        if ($ui.Phase -eq 'busy') { $e.Cancel = $true }
        elseif ($ui.Phase -eq 'download') { $e.Cancel = $true; $ui.Action = 'secondary' }
    }.GetNewClosure())
    $f.add_FormClosed({ $ui.Closed = $true; if (-not $ui.Action) { $ui.Action = 'close' } }.GetNewClosure())

    SuiteUiPage $ui 'progress'
    $title.Text = "Install $($SuiteCfg.name)"
    $sub.Text = 'Checking which applications are published'
    $b1.Visible = $false
    $b2.Text = 'Cancel'; $b2.Enabled = $false
    $f.ResumeLayout($false)
    $f.TopMost = $true
    $f.Show()
    $f.Activate()
    $f.TopMost = $false
    [Windows.Forms.Application]::DoEvents()
    $ui
}

function SuiteUiPage($ui, [string]$page) {
    $ui.Options.Visible = $page -eq 'options'
    $ui.Progress.Visible = $page -eq 'progress'
}

# 'busy' (closing refused), 'download' (closing or Cancel cancels), 'options' or 'done' (closing closes)
function SuiteUiPhase([string]$phase) {
    if (-not $SuiteUi -or $SuiteUi.Closed) { return }
    $SuiteUi.Phase = $phase
    $SuiteUi.Action = $null
    if ($phase -eq 'busy' -or $phase -eq 'download') {
        $SuiteUi.B1.Visible = $false
        $SuiteUi.B2.Text = 'Cancel'
        $SuiteUi.B2.Enabled = $phase -eq 'download'
    }
}

# Waits for a button or the window being closed; returns 'primary', 'secondary' or 'close'.
function SuiteUiWait {
    $SuiteUi.Action = $null
    while (-not $SuiteUi.Action -and -not $SuiteUi.Closed) { [Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 25 }
    if ($SuiteUi.Action) { $SuiteUi.Action } else { 'close' }
}

function SuiteUiRow($m, [string]$text, [string]$tone) {
    if (-not $SuiteUi -or $SuiteUi.Closed) { return }
    $l = $SuiteUi.States[$m.id]
    $l.Text = $text
    $l.ForeColor = switch ($tone) {
        'good' { [Drawing.Color]::FromArgb(16, 124, 16) }
        'bad' { [Drawing.Color]::FromArgb(176, 0, 32) }
        'busy' { [Drawing.SystemColors]::ControlText }
        default { [Drawing.SystemColors]::GrayText }
    }
    [Windows.Forms.Application]::DoEvents()
}

function SuiteCommandName($b) {
    $p = if ($b.kind -eq 'jar') { $b.launcher } else { $b.installPath }
    [IO.Path]::GetFileNameWithoutExtension($p)
}

# A box for all the applications starts as INSTALL_NO_* says, or else as their last installs chose: ticked,
# unticked, or (when they chose differently) indeterminate, which leaves each its own choice.
function SuiteOptState([string]$envValue, [string]$field, $records) {
    if ($envValue -eq '0') { return 'Checked' }
    if ($envValue) { return 'Unchecked' }
    $chosen = @($records | Where-Object { $_ -and $_.options } | ForEach-Object { [bool]$_.options.$field } | Select-Object -Unique)
    if ($chosen.Count -gt 1) { return 'Indeterminate' }
    if ($chosen.Count -eq 1 -and $chosen[0]) { return 'Unchecked' }
    return 'Checked'
}

# The options page. $manifests maps each id to its manifest ($null: not published); an id missing from it
# could not be checked. Returns the ids to install and sets INSTALL_NO_* and INSTALL_FORCE for their
# installers, or returns $null when cancelled.
function SuiteUiOptions($members, $manifests, [string[]]$only) {
    $ui = $SuiteUi
    $bins = @(); $records = @(); $current = 0; $published = 0
    foreach ($m in $members) {
        $cb = $ui.Picks[$m.id]; $info = $ui.Infos[$m.id]
        $rec = SuiteRecord $m
        if ($rec) { $records += $rec }
        if (-not $manifests.ContainsKey($m.id)) {
            $info.Text = 'could not be checked; see the log'
            $cb.Checked = if ($only) { $only -contains $m.id } else { -not $m.optional -or [bool]$rec }
            continue
        }
        $mf = $manifests[$m.id]
        if (-not $mf) { $info.Text = 'not published yet'; $cb.Checked = $false; $cb.Enabled = $false; continue }
        $want = SuiteWant $m $mf
        if (-not $want) { $info.Text = "$($m.version) not published yet"; $cb.Checked = $false; $cb.Enabled = $false; continue }
        $published++
        $entry = @($mf.versions) | Where-Object { $_.version -eq $want } | Select-Object -First 1
        $mb = @($entry.platforms.windows.binaries | Where-Object { $_ })
        $bins += @($mb | ForEach-Object { [pscustomobject]@{ App = $m.name; Bin = $_ } })
        if (-not $rec) { $info.Text = if ($m.optional) { "$want, optional" } else { "$want" } }
        elseif ($rec.version -eq $want) { $info.Text = "$want, installed"; if (-not $m.version) { $current++ } }
        else { $info.Text = "$want (installed: $($rec.version))" }
        # a pinned version is ticked even when installed: it may have been rebuilt since; an optional one is ticked
        # only once it is installed, to keep it up to date
        if ($only) { $cb.Checked = $only -contains $m.id }
        else { $cb.Checked = (-not $rec -and -not $m.optional) -or ($rec -and $rec.version -ne $want) -or [bool]$m.version }
    }
    $ui.Title.Text = "Install $($SuiteCfg.name)"
    $ui.Sub.Text = if ($published -gt 0 -and $current -eq $published) { 'Everything is installed and up to date. Tick an application to reinstall it.' }
                   else { 'Choose the applications to install.' }

    $desk = @($bins | Where-Object { $_.Bin.shortcuts -and $_.Bin.shortcuts.desktop }).Count -gt 0
    $menu = @($bins | Where-Object { $_.Bin.shortcuts -and $_.Bin.shortcuts.startMenu }).Count -gt 0
    $cmds = @($bins | Where-Object { $_.Bin.addToPath } | ForEach-Object { SuiteCommandName $_.Bin } | Select-Object -Unique)
    $withExts = @($bins | Where-Object { @($_.Bin.fileAssociations | Where-Object { $_ }).Count -gt 0 })
    $exts = @($withExts | ForEach-Object { @($_.Bin.fileAssociations) } | Where-Object { $_ } | ForEach-Object { $_.extension } | Select-Object -Unique)
    $rows = @()
    if ($desk -or $menu) {
        $where = if ($desk -and $menu) { 'on the desktop and in the Start menu' } elseif ($desk) { 'on the desktop' } else { 'in the Start menu' }
        $rows += [pscustomobject]@{ Key = 'INSTALL_NO_SHORTCUTS'; Text = "Create shortcuts $where"; State = (SuiteOptState $env:INSTALL_NO_SHORTCUTS 'noShortcuts' $records) }
    }
    if ($cmds.Count -gt 0) {
        $rows += [pscustomobject]@{ Key = 'INSTALL_NO_PATH'; Text = "Add to PATH, so $($cmds -join ', ') can be run from a terminal"; State = (SuiteOptState $env:INSTALL_NO_PATH 'noPath' $records) }
    }
    if ($exts.Count -gt 0) {
        $apps = @($withExts | ForEach-Object { $_.App } | Select-Object -Unique) -join ', '
        $rows += [pscustomobject]@{ Key = 'INSTALL_NO_ASSOCIATIONS'; Text = "Open $($exts -join ', ') files with $apps"; State = (SuiteOptState $env:INSTALL_NO_ASSOCIATIONS 'noAssociations' $records) }
    }
    for ($i = 0; $i -lt $ui.Checks.Count; $i++) {
        $cb = $ui.Checks[$i]
        # (Visible reads false while the page is hidden, so the Tag says which boxes are in use)
        $cb.Visible = $i -lt $rows.Count
        $cb.Tag = $null
        if ($i -lt $rows.Count) {
            $cb.Text = $rows[$i].Text; $cb.Tag = $rows[$i].Key
            $cb.ThreeState = $rows[$i].State -eq 'Indeterminate'
            $cb.CheckState = [Windows.Forms.CheckState]$rows[$i].State
        }
    }

    SuiteUiPage $ui 'options'
    SuiteUiPhase 'options'
    $ui.B1.Text = 'Install'; $ui.B1.Visible = $true; $ui.B1.Enabled = $true
    $ui.B2.Text = 'Cancel'; $ui.B2.Enabled = $true
    $ui.B1.Focus() | Out-Null
    while ($true) {
        if ((SuiteUiWait) -ne 'primary') { return $null }
        $ids = @($members | Where-Object { $ui.Picks[$_.id].Checked } | ForEach-Object { $_.id })
        if ($ids.Count -gt 0) { break }
        [void][Windows.Forms.MessageBox]::Show($ui.Form, 'Tick at least one application to install.', $ui.Form.Text,
            [Windows.Forms.MessageBoxButtons]::OK, [Windows.Forms.MessageBoxIcon]::Warning)
    }
    # what the boxes say goes for every installer; an indeterminate box leaves each its last install's choice
    foreach ($cb in $ui.Checks) {
        if (-not $cb.Tag) { continue }
        switch ($cb.CheckState) {
            'Checked' { [Environment]::SetEnvironmentVariable($cb.Tag, '0', 'Process') }
            'Unchecked' { [Environment]::SetEnvironmentVariable($cb.Tag, '1', 'Process') }
        }
    }
    # as in an application's own window, pressing Install is the go-ahead to reinstall what is current, so
    # changed choices are applied (files that are already current are not downloaded again)
    [Environment]::SetEnvironmentVariable('INSTALL_FORCE', '1', 'Process')
    foreach ($m in $members) {
        if ($ids -contains $m.id) { SuiteUiRow $m 'waiting' }
        elseif (SuiteUnpublished $m $manifests) { SuiteUiRow $m 'not published yet' }
        else { SuiteUiRow $m 'not selected' }
    }
    SuiteUiPage $ui 'progress'
    $ui.Title.Text = "Installing $($SuiteCfg.name)"
    $ui.Sub.Text = "$(@($members | Where-Object { $ids -contains $_.id } | ForEach-Object { $_.name }) -join ', ')"
    $ids
}

# The last page: what happened to each application. Returns when the window is closed.
function SuiteUiFinish($results, [bool]$cancelled) {
    if (-not $SuiteUi -or $SuiteUi.Closed) { return }
    $ui = $SuiteUi
    $name = $SuiteCfg.name
    try {
        SuiteUiPage $ui 'progress'
        SuiteUiPhase 'done'
        $ui.B2.Text = 'Close'; $ui.B2.Enabled = $true
        $ui.Form.AcceptButton = $ui.B2
        $done = @($results | Where-Object { $_.Result -eq 'installed' })
        $failed = @($results | Where-Object { $_.Result -eq 'failed' })
        if ($cancelled) {
            $ui.Title.Text = "$name was not fully installed"
            $ui.Status.Text = "Cancelled. $(if ($done.Count) { "Installed: $(($done | ForEach-Object { $_.Member.name }) -join ', ')." } else { 'Nothing was installed.' })"
            SuiteBar 0
        } elseif ($failed.Count -gt 0) {
            $ui.Title.Text = "$name was not fully installed"
            $ui.Status.ForeColor = [Drawing.Color]::FromArgb(176, 0, 32)
            $ui.Status.Text = "Not installed: $(($failed | ForEach-Object { $_.Member.name }) -join ', '). The log below says why."
            SuiteBar 0
            if ($ui.Report) { $ui.B1.Text = 'Open report'; $ui.B1.Visible = $true }
        } else {
            $ui.Title.Text = "$name is installed"
            $ui.Status.Text = "Installed: $(($done | ForEach-Object { $_.Member.name }) -join ', '). Each has its own entry in Settings > Apps."
            SuiteBar 100
        }
        while ($true) {
            switch (SuiteUiWait) {
                'primary' { try { Start-Process -FilePath $ui.Report } catch { } }
                default { return }
            }
        }
    } finally {
        SuiteUiClose
    }
}

function SuiteUiClose {
    if (-not $SuiteUi.Closed) { $SuiteUi.Phase = 'done'; $SuiteUi.Form.Close() }
    $SuiteUi.Form.Dispose()
}

# ---- install ---------------------------------------------------------------------------

function SuiteInstall([bool]$quiet) {
    $ProgressPreference = 'SilentlyContinue'
    if ($env:OS -ne 'Windows_NT') { throw "$($SuiteCfg.name): this installer supports Windows only for now." }
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

    $members = @($SuiteCfg.members)
    $only = @()
    if ($env:INSTALL_ONLY) {
        $only = @($env:INSTALL_ONLY -split '[,; ]+' | Where-Object { $_ } | ForEach-Object { $_.ToLowerInvariant() })
        $known = @($members | ForEach-Object { $_.id })
        $unknown = @($only | Where-Object { $known -notcontains $_ })
        if ($unknown.Count -gt 0) { throw "INSTALL_ONLY names $($unknown -join ', '), which the suite does not have. It has: $($known -join ', ')" }
    }

    # Every option this changes for the applications' installers, to be put back afterwards.
    $saved = @{}
    foreach ($n in 'INSTALL_VERSION', 'INSTALL_DIR', 'INSTALL_QUIET', 'INSTALL_FORCE', 'INSTALL_NO_SHORTCUTS', 'INSTALL_NO_PATH', 'INSTALL_NO_ASSOCIATIONS') {
        $saved[$n] = [Environment]::GetEnvironmentVariable($n, 'Process')
    }
    $SuiteUi = $null
    if (SuiteWantsWindow $quiet) {
        try { $SuiteUi = SuiteUiOpen $members } catch { $SuiteUi = $null; Write-Warning "Could not open the installer window ($($_.Exception.Message)); continuing here." }
    }
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("vi-suite-" + [guid]::NewGuid().ToString('N').Substring(0, 8))
    New-Item -ItemType Directory -Force -Path $tmp | Out-Null
    $results = @()
    $cancelled = $false
    $broke = $false
    $chosen = $null
    try {
        # Per-application options would apply to every application here, so they are set aside.
        foreach ($n in 'INSTALL_VERSION', 'INSTALL_DIR') {
            if ($saved[$n]) {
                SuiteSay "$n applies to one application and is ignored here; run that application's own installer to use it." Yellow
                [Environment]::SetEnvironmentVariable($n, $null, 'Process')
            }
        }
        # Each application's installer would open a window of its own, one after another; the suite keeps
        # them all in this console, or in its own window.
        [Environment]::SetEnvironmentVariable('INSTALL_QUIET', '1', 'Process')

        $manifests = $null
        if ($SuiteUi) {
            # what each application would install, for the options page
            $manifests = @{}
            SuiteUiPhase 'download'
            foreach ($m in $members) {
                try { $manifests[$m.id] = SuiteFetchManifest $m $tmp }
                catch {
                    if ($SuiteUi.Action -eq 'secondary') { $cancelled = $true; break }
                    SuiteSay "ERROR: $($m.name): $($_.Exception.Message)" Red
                }
            }
            if (-not $cancelled) { $chosen = SuiteUiOptions $members $manifests $only }
            if (-not $chosen) {
                SuiteSay 'Cancelled. Nothing was installed.'
                return $false
            }
            SuiteUiPhase 'download'
        } else {
            if ($only.Count -gt 0) { $members = @($members | Where-Object { $only -contains $_.id }) }
            # an optional application only when asked for by name, or to keep one already installed up to date
            $chosen = @($members | Where-Object { $only.Count -gt 0 -or -not $_.optional -or (SuiteRecord $_) } | ForEach-Object { $_.id })
        }

        SuiteSay "Installing $($SuiteCfg.name): $(($members | Where-Object { $chosen -contains $_.id } | ForEach-Object { $_.name }) -join ', ')"
        foreach ($m in $members) {
            if ($chosen -notcontains $m.id) {
                $r = if (SuiteUnpublished $m $manifests) { 'unpublished' } else { 'skipped' }
                $results += [pscustomobject]@{ Member = $m; Result = $r }
                continue
            }
            if ($cancelled) {
                SuiteUiRow $m 'cancelled'
                $results += [pscustomobject]@{ Member = $m; Result = 'cancelled' }
                continue
            }
            if ($SuiteUi) { SuiteUiRow $m 'installing...' 'busy'; $SuiteUi.Status.Text = "Installing $($m.name)"; SuiteBar -1 }
            $r = SuiteInstallOne $m $tmp $manifests
            if ($SuiteUi -and $SuiteUi.Action -eq 'secondary') {
                $cancelled = $true
                if ($r -eq 'failed') { $r = 'cancelled' }
            }
            switch ($r) {
                'installed' { SuiteUiRow $m "installed $(SuiteRecordVersion $m)" 'good' }
                'unpublished' { SuiteUiRow $m 'not published yet' }
                'cancelled' { SuiteUiRow $m 'cancelled' }
                default { SuiteUiRow $m 'failed; see the log' 'bad' }
            }
            $results += [pscustomobject]@{ Member = $m; Result = $r }
        }
    } catch {
        $broke = $true
        throw
    } finally {
        foreach ($n in $saved.Keys) { [Environment]::SetEnvironmentVariable($n, $saved[$n], 'Process') }
        Remove-Item -Recurse -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
        # cancelled on the options page, or something went wrong: the window just closes
        if ($SuiteUi -and (-not $chosen -or $broke)) { SuiteUiClose; $SuiteUi = $null }
    }

    SuiteSay ""
    SuiteSay "$($SuiteCfg.name):" Cyan
    foreach ($r in $results) {
        switch ($r.Result) {
            'installed' { SuiteSay ("    {0,-20} {1}" -f $r.Member.name, (SuiteRecordVersion $r.Member)) Green }
            'unpublished' { SuiteSay ("    {0,-20} not published yet" -f $r.Member.name) Yellow }
            'skipped' { SuiteSay ("    {0,-20} not selected" -f $r.Member.name) }
            'cancelled' { SuiteSay ("    {0,-20} cancelled" -f $r.Member.name) Yellow }
            default { SuiteSay ("    {0,-20} FAILED (see above)" -f $r.Member.name) Red }
        }
    }
    if ($SuiteUi) { SuiteUiFinish $results $cancelled; $SuiteUi = $null }
    return -not $cancelled -and @($results | Where-Object { $_.Result -eq 'failed' }).Count -eq 0
}

$SuiteQuiet = $false
$SuiteEverything = $env:INSTALL_EVERYTHING -eq '1'
foreach ($SuiteA in $args) {
    switch -Regex ($SuiteA) {
        '^(-Quiet|--do-not-prompt-me)$' { $SuiteQuiet = $true }
        '^--install-everything$' { $SuiteEverything = $true }
        default { Write-Warning "Ignoring unknown argument: $SuiteA" }
    }
}
# everything: the optional applications are treated like the rest (INSTALL_ONLY still says which, when set)
if ($SuiteEverything) { foreach ($SuiteM in @($SuiteCfg.members | Where-Object { $_.optional })) { $SuiteM.optional = $false } }
$SuiteOk = $false
try {
    $SuiteOk = [bool](SuiteInstall $SuiteQuiet | Select-Object -Last 1)
} catch {
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
}
if (-not $SuiteOk -and $PSCommandPath) { exit 1 }
